def upper_bound(a, x):
    # leftmost index i with a[i] > x (so x would insert AFTER any equal elements)
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def count_between(a, lo, hi):
    # how many elements satisfy lo <= v <= hi, INCLUSIVE; 0 when lo > hi
    if lo > hi:
        return 0
    return upper_bound(a, hi) - lower_bound(a, lo)

def insert_sorted(a, x):
    # NEW list with x placed at upper_bound(a, x); `a` is not mutated
    idx = upper_bound(a, x)
    return a[:idx] + [x] + a[idx:]

