class CircuitBreaker:
    def __init__(self, fail_threshold, reset_timeout, half_open_successes=1):
        self.fail_threshold = fail_threshold
        self.reset_timeout = reset_timeout
        self.half_open_successes = half_open_successes
        self._state = 'closed'
        self._failure_count = 0
        self._opened_at = 0
        self._half_open_successes_total = 0

    def state(self, now):
        if self._state == 'closed':
            return 'closed'
        elif self._state == 'open':
            if now - self._opened_at >= self.reset_timeout:
                self._state = 'half_open'
                self._half_open_successes_total = 0
            return self._state
        elif self._state == 'half_open':
            if now >= self._opened_at:
                return self._state
            return 'open'
        return 'closed'

    def allow(self, now):
        return self._state == 'closed' or self._state == 'half_open'

    def record(self, now, ok):
        if self._state == 'closed':
            if ok:
                self._failure_count = 0
            else:
                self._failure_count += 1
                if self._failure_count >= self.fail_threshold:
                    self._state = 'open'
                    self._opened_at = now
        elif self._state == 'open':
            # Transition to half_open happens automatically in state(),
            # but record() needs to know the current state at this time
            current_state = self.state(now)
            if current_state == 'open':
                # block the request
                pass
            elif current_state == 'half_open':
                if ok:
                    self._half_open_successes_total += 1
                    if self._half_open_successes_total >= self.half_open_successes:
                        self._state = 'closed'
                        self._failure_count = 0
                        self._half_open_successes_total = 0
                else:
                    self._state = 'open'
                    self._opened_at = now
        elif self._state == 'half_open':
            if ok:
                self._half_open_successes_total += 1
                if self._half_open_successes_total >= self.half_open_successes:
                    self._state = 'closed'
                    self._failure_count = 0
                    self._half_open_successes_total = 0
            else:
                self._state = 'open'
                self._opened_at = now

