def dedup_last(xs):
    # drop earlier duplicates, keep each value at its LAST position
    if not xs:
        return []
    # Find the last position of each element
    last_pos = {}
    for i, x in enumerate(xs):
        last_pos[x] = i
    # Build result by iterating in reverse and keeping only last occurrences
    result = []
    seen = set()
    for i in range(len(xs) - 1, -1, -1):
        x = xs[i]
        if x not in seen:
            seen.add(x)
            result.append(x)
    # Reverse to get correct order
    return result[::-1]

