class CircuitBreaker:
    def __init__(self, fail_threshold, reset_timeout, half_open_successes=1):
        self.fail_threshold = fail_threshold
        self.reset_timeout = reset_timeout
        self.half_open_successes = half_open_successes
        self._state = 'closed'
        self._failures = 0
        self._last_change_time = 0.0

    def state(self, now):
        if self._state == 'closed':
            return 'closed'
        elif self._state == 'open':
            if now >= self._last_change_time + self.reset_timeout:
                self._state = 'half_open'
                self._last_change_time = now
                return 'half_open'
            return 'open'
        else:  # 'half_open'
            return 'half_open'

    def allow(self, now):
        return self.state(now) != 'open'

    def record(self, now, ok):
        self._state = self.state(now)
        if self._state == 'open':
            self._failures += 1
        elif self._state == 'half_open':
            if ok:
                self._failures = 0
                if self._failures < self.half_open_successes:
                    self._failures += 1
                else:
                    self._failures = 0
                    self._state = 'closed'
            else:
                self._state = 'open'
                self._last_change_time = now

