def count_regions(grid):
    # grid: list of equal-length strings, '#' is filled and '.' is empty.
    # Count connected groups of '#' using 4-way (up/down/left/right) adjacency.
    if not grid:
        return 0
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])
    visited = [[False] * n for _ in range(m)]

    count = 0

    def bfs(start_row, start_col):
        queue = [(start_row, start_col)]
        visited[start_row][start_col] = True
        while queue:
            row, col = queue.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = row + dr, col + dc
                if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == '#':
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '#' and not visited[i][j]:
                count += 1
                bfs(i, j)

    return count

