def group_stats(rows, key_field, value_field):
    # rows: list of dicts. Group by rows[key_field]; per group return
    # {'count': int, 'sum': number, 'min': number, 'max': number, 'avg': float}.
    # A row missing either field raises KeyError.
    groups = {}
    for row in rows:
        if key_field not in row or value_field not in row:
            raise KeyError
        key = row[key_field]
        value = row[value_field]
        if key not in groups:
            groups[key] = []
        groups[key].append(value)

    result = {}
    for key, values in groups.items():
        result[key] = {
            'count': len(values),
            'sum': sum(values),
            'min': min(values),
            'max': max(values),
            'avg': sum(values) / len(values)
        }
    return result

