def isqrt(n):
    # floor of the square root, exact for huge ints. Do NOT use math.isqrt or floats.
    if n < 0:
        raise ValueError("isqrt() argument must be non-negative")
    if n == 0:
        return 0
    # Use Newton's method for integer square root
    x = n
    y = (x + 1) // 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return x

def is_perfect_square(n):
    if n < 0:
        return False
    return isqrt(n) * isqrt(n) == n

