def longest_common_substring(a, b):
    # the longest CONTIGUOUS run present in both. On a tie, the one starting earliest in `a`.
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_len = 0
    max_start = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    max_start = i - max_len
            else:
                dp[i][j] = 0
    return a[max_start:max_start + max_len]

