def group_stats(rows, key_field, value_field):
    # rows: list of dicts. Group by rows[key_field]; per group return
    # {'count': int, 'sum': number, 'min': number, 'max': number, 'avg': float}.
    # A row missing either field raises KeyError.
    groups = {}
    for row in rows:
        key = row[key_field]
        if key not in groups:
            groups[key] = {'count': 0, 'sum': 0, 'min': None, 'max': None, 'values': []}
        groups[key]['values'].append(row[value_field])

    result = {}
    for key, data in groups.items():
        values = data['values']
        count = len(values)
        total = sum(values)
        min_val = min(values)
        max_val = max(values)
        avg = total / count
        result[key] = {
            'count': count,
            'sum': total,
            'min': min_val,
            'max': max_val,
            'avg': avg
        }
    return result

