def count_regions(grid):
    # grid: list of equal-length strings, '#' is filled and '.' is empty.
    # Count connected groups of '#' using 4-way (up/down/left/right) adjacency.
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0

    def dfs(r, c):
        # Mark current cell as visited
        visited[r][c] = True

        # Check all 4 directions: up, down, left, right
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == '#':
                    dfs(nr, nc)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#' and not visited[r][c]:
                count += 1
                dfs(r, c)

    return count

