def isqrt(n):
    if n < 0:
        raise ValueError("isqrt() arg must be non-negative")
    if n == 0:
        return 0
    # Binary search for floor(sqrt(n))
    # We want the largest x such that x*x <= n
    # Start with left=0, right=n
    # Invariant: answer is in [left, right)
    left, right = 0, n
    while left < right:
        mid = (left + right + 1) // 2  # round up
        if mid * mid <= n:
            left = mid  # mid is our answer, possibly
        else:
            right = mid - 1
    return left

