UNRESERVED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~'

def percent_encode(s):
    # UTF-8 encode, then %XX (UPPERCASE hex) every byte outside UNRESERVED
    reserved = set(UNRESERVED)
    result = []
    for byte in s.encode('utf-8'):
        if byte in reserved:
            result.append(chr(byte))
        else:
            result.append('%{:02X}'.format(byte))
    return ''.join(result)

def percent_decode(s):
    # inverse; %xx is case-insensitive. ValueError on a truncated/invalid escape or bad UTF-8.
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%':
            if i + 2 >= len(s):
                raise ValueError('truncated % sequence')
            hex_digits = s[i+1:i+3]
            try:
                byte = int(hex_digits, 16)
            except ValueError:
                raise ValueError('invalid hex in %% sequence: %r' % hex_digits)
            result.append(byte)
            i += 3
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result).decode('utf-8')

