def run(program):
    # program: list of (op, *args). Return final top of stack.
    stack = []
    variables = {}

    for op in program:
        if op[0] == 'push':
            stack.append(op[1])
        elif op[0] == 'add':
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op[0] == 'sub':
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op[0] == 'mul':
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op[0] == 'dup':
            top = stack[-1]
            stack.append(top)
        elif op[0] == 'load':
            var_name = op[1]
            stack.append(variables[var_name])
        elif op[0] == 'store':
            var_name = op[1]
            variables[var_name] = stack.pop()

    return stack[-1]

