class Ok:
    def __init__(self, value):
        self.value = value
        raise NotImplementedError

    def is_ok(self):
        return True

    def map(self, f):
        return Ok(f(self.value))

    def map_err(self, f):
        return self

    def and_then(self, f):
        return f(self.value)

    def unwrap(self):
        return self.value

    def unwrap_or(self, default):
        return self.value

    def __eq__(self, other):
        if isinstance(other, Ok):
            return self.value == other.value
        return False

    def __hash__(self):
        return hash((type(self), self.value))


class Err:
    def __init__(self, error):
        self.error = error
        raise NotImplementedError

    def is_ok(self):
        return False

    def map(self, f):
        return self

    def map_err(self, f):
        return Err(f(self.error))

    def and_then(self, f):
        return self

    def unwrap(self):
        raise ValueError('unwound Err')

    def unwrap_or(self, default):
        return default

    def __eq__(self, other):
        if isinstance(other, Err):
            return self.error == other.error
        return False

    def __hash__(self):
        return hash((type(self), self.error))


def combine(results):
    """
    Combine a list of Result values:
    - If all are Ok, return Ok([values...])
    - Otherwise return Err([errors...]) with all errors in order
    """
    errors = []
    values = []
    for result in results:
        if result.is_ok():
            values.append(result.value)
        else:
            errors.append(result.error)
    if errors:
        return Err(errors)
    return Ok(values)


def attempt(fn, *args):
    """
    Wrap a function call in a Result.
    - If fn(*args) returns a value, return Ok(value)
    - If fn(*args) raises an exception, return Err(str(exception))
    """
    try:
        return fn(*args)
    except Exception as e:
        return Err(str(e))

