def percent_encode(s):
    # UTF-8 encode, then %XX (UPPERCASE hex) every byte outside UNRESERVED
    s_bytes = s.encode('utf-8')
    encoded = bytearray()
    for byte in s_bytes:
        if byte in UNRESERVED:
            encoded.append(byte)
        else:
            hex_val = f'{byte:02X}'
            encoded.extend(b'%' + hex_val.encode())
    return encoded.decode('ascii')

def percent_decode(s):
    # inverse; %xx is case-insensitive. ValueError on a truncated/invalid escape or bad UTF-8.
    s = s.upper()
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%':
            if i + 2 >= len(s):
                raise ValueError('truncated percent escape')
            hex_chars = s[i+1:i+3]
            try:
                byte_val = int(hex_chars, 16)
            except ValueError:
                raise ValueError(f'invalid percent sequence: %{hex_chars}')
            result.append(byte_val)
            i += 3
        else:
            result.append(ord(s[i]))
            i += 1
    return result.decode('utf-8')

