    def eval(self, expr):
        tokens = expr.split()
        if len(tokens) == 1:
            return float(tokens[0])
        # Start with first number
        result = float(tokens[0])
        # Process remaining tokens in pairs: (number, operator)
        i = 1
        while i < len(tokens):
            num = float(tokens[i])
            # Look ahead to find the operator after this number
            j = i + 1
            while j < len(tokens) and tokens[j].lstrip('-').isdigit():
                j += 1
            # tokens[j] should be an operator
            if j >= len(tokens):
