def add(p, q):
    if not p or not q:
        return []
    max_len = max(len(p), len(q))
    extended_p = p + [0] * (max_len - len(p))
    extended_q = q + [0] * (max_len - len(q))
    result = [extended_p[i] + extended_q[i] for i in range(max_len)]
    if not result or all(x == 0 for x in result):
        return []
    return result

def mul(p, q):
    if not p or not q:
        return []
    result = []
    for i, pi in enumerate(p):
        for j, qj in enumerate(q):
            result[i + j] = result[i + j] + pi * qj
    if not result or all(x == 0 for x in result):
        return []
    return result

