class Calc:
    def eval(self, expr):
        tokens = expr.split()
        if not tokens:
            return 0

        # Handle case with just a number
        if len(tokens) == 1:
            return int(tokens[0])

        # Parse tokens: numbers and operators
        vals = []
        ops = []

        i = 0
        while i < len(tokens):
            if tokens[i].isdigit():
                vals.append(int(tokens[i]))
            elif tokens[i] in '+-*/':
                ops.append(tokens[i])
            i += 1

        # Evaluate left-to-right
        result = vals[0]
        for op in ops:
            if op == '+':
                result += vals[1]
            elif op == '-':
                result -= vals[1]
            elif op == '*':
                result *= vals[1]
            elif op == '/':
                result /= vals[1]
            vals.pop(0)

        return result

