def area(poly):
    # absolute polygon area from its vertices (floats), 0.0 for degenerate input
    if len(poly) < 3:
        return 0.0

    # Shoelace formula
    area = 0.0
    for i in range(len(poly)):
        j = (i + 1) % len(poly)
        area += poly[i][0] * poly[j][1]
        area -= poly[j][0] * poly[i][1]
    return abs(area) / 2.0

def orientation(poly):
    # 'ccw' | 'cw' | 'degenerate'
    if len(poly) < 3:
        return 'degenerate'

    # Cross product of vectors (p1->p2) and (p1->p3)
    p1 = poly[0]
    p2 = poly[1]
    p3 = poly[2]

    cross = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    if cross == 0:
        return 'degenerate'
    elif cross > 0:
        return 'ccw'
    else:
        return 'cw'

