def slugify(text):
    # lowercase
    result = text.lower()

    # Replace every run of non-alphanumeric ASCII with a single hyphen
    new_result = []
    prev_is_hyphen = False
    for char in result:
        if char.isalnum():
            new_result.append(char)
            prev_is_hyphen = False
        else:
            if not prev_is_hyphen and new_result:
                new_result.append('-')
                prev_is_hyphen = True
            elif not new_result:
                prev_is_hyphen = True

    result = ''.join(new_result)

    # Remove leading/trailing hyphens
    result = result.strip('-')

    return result

