class DisjointSet:
    def __init__(self):
        # `count` is a plain attribute: the number of distinct components right now
        self.count = 0
        self.parent = {}
        self.rank = {}
        self.size = {}

    def add(self, x):
        # True if x was new, False if it was already known
        if x not in self.parent:
            self.parent[x] = x
            self.rank[x] = 0
            self.size[x] = 1
            self.count += 1
            return True
        return False

    def find(self, x):
        # representative of x's component; KeyError if x is unknown
        if x not in self.parent:
            raise KeyError(x)
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        # Path compression
        while self.parent[root] != root:
            curr = root
            root = self.parent[root]
            self.parent[curr] = root
        return root

    def union(self, a, b):
        # adds either element if unknown; True if two components were merged, False if they
        # were already the same
        if a not in self.parent:
            self.add(a)
        if b not in self.parent:
            self.add(b)
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False
        # Union by rank
        if self.rank[root_a] < self.rank[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        if self.rank[root_a] == self.rank[root_b]:
            self.rank[root_a] += 1
        self.count -= 1
        return True

    def connected(self, a, b):
        try:
            return self.find(a) == self.find(b)
        except KeyError:
            return False

    def size_of(self, x):
        # how many elements are in x's component
        root = self.find(x)
        return self.size[root]

    def groups(self):
        # list of components, each sorted, the list itself sorted by each group's first member
        groups = []
        seen = set()
        for x in self.parent:
            root = self.find(x)
            if root not in seen:
                seen.add(root)
                group = []
                for x in self.parent:
                    if self.find(x) == root:
                        group.append(x)
                group.sort()
                groups.append(group)
        groups.sort(key=lambda g: g[0])
        return groups

